export function chainRelations(data,node=''){
 return CATALOG.flatMap(c=>c.nodes.map(n=>{const [stage,claimId]=specific[c.id]?.[n]||['产品 / 业务资料',null];const fact=claimId&&data.claims.find(f=>f.id===claimId);const archived=claimId&&!fact;const source=fact?data.sources.find(s=>s.id===fact.source):null;return {id:c.id+':'+n,company:c.id,node:n,stage:archived?'原事实已被替代，待重核':stage,claimId:fact?.id||null,claim:fact||null,source:{title:source?.title||c.sourceTitle,url:source?.url||c.source,published:source?.date||c.date,locator:fact?.locator||'产品 / 项目介绍'},text:fact?.text||c.description,boundary:fact?.boundary||'仅支持所列产品、项目或应用关系；未核实人形收入拆分与客户供货。',humanRevenue:false,review:'资料核对 / 未经研究员确认'};})).filter(r=>!node||r.node===node);
}
export function chainCoverage(data){const rows=chainRelations(data);return {nodes:CHAIN_NODES.length,companies:new Set(rows.map(r=>r.company)).size,relationships:rows.length,deepFacts:new Set(rows.filter(r=>r.claimId).map(r=>r.claimId)).size,gaps:data.claims.filter(c=>c.grade==='E').length};}
export function chainExport(data,node){const n=chainNode(node),rows=chainRelations(data,n.id);return '# 人形机器人产业研究 · '+n.name+'\n\n导出 '+new Date().toISOString()+'\n核查 '+CHECKED_AT+'；历史资料与本地iFinD快照；非自动订阅。\n\n'+n.role+'\n\n研究问题：'+n.question+'\n\n## 技术与经营框架（研究判断，非公司已实现数据）\n\n'+n.routes.map(r=>'### '+r.name+'\n'+r.mechanism+'\n核查：'+r.check+(r.source?'\n来源：'+TECH_SOURCES[r.source].url:'\n专属原文：未获取')).join('\n\n')+'\n\n'+n.variables.map(v=>'### '+v.name+'\n核查指标：'+v.signal+'\n财务机制（条件性）：'+v.financial+'\n反向条件：'+v.counter).join('\n\n')+'\n\n## 公司与业务关系\n\n'+rows.map(r=>'### '+companyById(r.company).name+' · '+r.stage+'\n'+r.text+'\n'+(r.claim?'原披露名称：'+(r.claim.disclosedName||'未披露')+'\n适用期间：'+r.claim.periodStart+' — '+r.claim.periodEnd+'\n证据：'+r.claimId:'无已核验独立人形收入')+'\n边界：'+r.boundary+'\n来源：'+r.source.title+'\n'+r.source.url+'\n材料日期：'+(r.source.published||'网页未标注')+'；核查：'+CHECKED_AT+'\n定位：'+r.source.locator).join('\n\n')+'\n\n## 未解决问题\n\n'+n.gap+'\n功能连线不是供货关系；不构成投资建议。\n';}
